// CALAO — Code — Parse RSS
// Version 3 — source_id garanti depuis Split
// Gère RSS 2.0 et Atom 1.0
// Extrait : titre, résumé, date, url, image
// Fenêtre : 30 jours
// ============================================================

const crypto = require('crypto');

const inputItem = $('Split — Une source RSS par item').item.json;
const sourceId  = inputItem.id;
const sourceNom = inputItem.nom;
const semaineId = inputItem.semaine_id;

if (!sourceId) {
  throw new Error(`source_id manquant — vérifier le nœud Split`);
}

const xmlRaw = $input.item.json.data
            || $input.item.json.body
            || '';

if (!xmlRaw || xmlRaw.trim() === '') {
  throw new Error(`RSS vide : ${sourceNom}`);
}

function extraireTexte(xml, balise) {
  try {
    const cdata = new RegExp(
      `<${balise}[^>]*><!\\[CDATA\\[([\\s\\S]*?)\\]\\]><\\/${balise}>`, 'i'
    );
    const mc = xml.match(cdata);
    if (mc) return mc[1].trim();
    const simple = new RegExp(
      `<${balise}[^>]*>([\\s\\S]*?)<\\/${balise}>`, 'i'
    );
    const ms = xml.match(simple);
    if (ms) return ms[1].replace(/<[^>]+>/g, '').trim();
    return null;
  } catch(e) { return null; }
}

function extraireAttribut(xml, balise, attribut) {
  try {
    const reg = new RegExp(
      `<${balise}[^>]*${attribut}=[\"']([^\"']*)[\"'][^>]*>`, 'i'
    );
    const m = xml.match(reg);
    return m ? m[1].trim() : null;
  } catch(e) { return null; }
}

function extraireImage(itemXml) {
  let img = extraireAttribut(itemXml, 'media:content', 'url');
  if (img) return img;
  const enc1 = /<enclosure[^>]*type=[\"']image[^\"']*[\"'][^>]*url=[\"']([^\"']*)[\"']/i;
  const em1 = itemXml.match(enc1);
  if (em1) return em1[1];
  const enc2 = /<enclosure[^>]*url=[\"']([^\"']*)[\"'][^>]*type=[\"']image[^\"']*[\"']/i;
  const em2 = itemXml.match(enc2);
  if (em2) return em2[1];
  const imgTag = /<img[^>]*src=[\"']([^\"']*)[\"']/i;
  const eim = itemXml.match(imgTag);
  if (eim) return eim[1];
  return null;
}

function normaliserDate(dateStr) {
  if (!dateStr) return null;
  try {
    const normalise = dateStr
      .trim()
      .replace(/\bGMT\b/, '+0000')
      .replace(/\bUTC\b/, '+0000');
    const d = new Date(normalise);
    return isNaN(d.getTime()) ? null : d.toISOString();
  } catch(e) { return null; }
}

function genererHash(titre) {
  if (!titre) return null;
  const n = titre
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9]/g, '')
    .trim();
  return crypto.createHash('md5').update(n).digest('hex');
}

function articleRecent(dateStr, joursMax) {
  if (!dateStr) return false;
  const date = new Date(dateStr);
  const limite = new Date();
  limite.setDate(limite.getDate() - joursMax);
  return date >= limite;
}

const isAtom = xmlRaw.includes('<feed') &&
  xmlRaw.includes('xmlns="http://www.w3.org/2005/Atom"');

const baliseItem   = isAtom ? 'entry'   : 'item';
const baliseDate   = isAtom ? 'updated' : 'pubDate';
const baliseResume = isAtom ? 'summary' : 'description';

const itemRegex = new RegExp(
  `<${baliseItem}[\\s>][\\s\\S]*?<\\/${baliseItem}>`, 'gi'
);
const itemsXml = xmlRaw.match(itemRegex) || [];

console.log(`[${sourceNom}] Items trouvés: ${itemsXml.length}`);

if (itemsXml.length === 0) {
  console.log(`[${sourceNom}] Aucun item dans le flux — skip`);
  return [{ json: { source_nom: sourceNom, articles_count: 0, skip: true } }];
}

const articles = [];

for (const itemXml of itemsXml) {
  try {
    const titre = extraireTexte(itemXml, 'title');
    if (!titre) continue;
    let url = null;
    if (isAtom) {
      url = extraireAttribut(itemXml, 'link', 'href');
    } else {
      url = extraireTexte(itemXml, 'link');
      if (!url) url = extraireAttribut(itemXml, 'link', 'href');
    }
    if (!url || url.trim() === '') continue;
    const dateStr = extraireTexte(itemXml, baliseDate)
                 || extraireTexte(itemXml, 'dc:date')
                 || extraireTexte(itemXml, 'published');
    const dateNorm = normaliserDate(dateStr);
    if (!articleRecent(dateNorm, 30)) continue;
    const resume = extraireTexte(itemXml, baliseResume)
                || extraireTexte(itemXml, 'content')
                || extraireTexte(itemXml, 'content:encoded');
    const imageUrl = extraireImage(itemXml);
    const hash = genererHash(titre);
    if (!hash) continue;
    articles.push({
      json: {
        source_id:        sourceId,
        source_nom:       sourceNom,
        semaine_id:       semaineId,
        titre:            titre.substring(0, 500),
        resume:           resume ? resume.substring(0, 2000) : null,
        url:              url.trim(),
        image_url:        imageUrl || null,
        image_valide:     imageUrl ? true : false,
        date_publication: dateNorm,
        doublons_hash:    hash,
        selectionne:      false
      }
    });
  } catch(e) { continue; }
}

console.log(`[${sourceNom}] Articles valides après filtrage: ${articles.length}`);

if (articles.length === 0) {
  return [{ json: { source_nom: sourceNom, articles_count: 0, skip: true } }];
}

return articles;

// Gestion erreur HTTP — source inaccessible
const sourceId  = $('Split — Une source RSS par item').item.json.id;
const sourceNom = $('Split — Une source RSS par item').item.json.nom;
const erreur    = $input.item.json.error?.message || 'Erreur inconnue';
console.log(`[CALAO] Erreur RSS — ${sourceNom} : ${erreur}`);
return [{ json: { source_id: sourceId, source_nom: sourceNom, erreur } }];

// CALAO — Normaliser résultats SerpAPI Google News
const crypto = require('crypto');

function getISOWeek(date) {
  const d = new Date(date);
  d.setHours(0,0,0,0);
  d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
  const week1 = new Date(d.getFullYear(), 0, 4);
  return 1 + Math.round(((d.getTime()-week1.getTime())/86400000 - 3 + (week1.getDay()+6)%7)/7);
}
const now = new Date();
const semaine_id = `${now.getFullYear()}-W${String(getISOWeek(now)).padStart(2,'0')}`;

const reponse = $input.first().json;
const newsResults = reponse.news_results || reponse.top_stories || [];

const articles = [];
for (const item of newsResults) {
  const titre = (item.title || '').trim();
  const url   = item.link || item.url || '';
  if (!titre || !url) continue;
  const hash = crypto.createHash('sha256')
    .update(titre.toLowerCase().replace(/[^a-z0-9]/g,'').substring(0,60))
    .digest('hex').substring(0,16);
  articles.push({ json: {
    source_id: '395f74c8-5fab-4308-afa6-e42a0aba5e5b',
    source_nom:       (item.source && item.source.name) ? item.source.name : 'SerpAPI',
    titre,
    resume:           item.snippet || item.description || '',
    url,
    image_url:        item.thumbnail || null,
    image_valide:     !!item.thumbnail,
    date_publication: item.date ? new Date(item.date).toISOString() : new Date().toISOString(),
    doublons_hash:    hash,
    semaine_id,
    selectionne:      false,
    collecteur:       'serpapi'
  }});
}

console.log(`[CALAO SerpAPI] ${articles.length} articles normalisés`);
if (articles.length === 0) return [{ json: { skip: true } }];
return articles;

// CALAO — Normaliser résultats Tavily
const crypto = require('crypto');

function getISOWeek(date) {
  const d = new Date(date);
  d.setHours(0,0,0,0);
  d.setDate(d.getDate() + 3 - (d.getDay() + 6) % 7);
