}
const now = new Date();
const semaine_id = `${now.getFullYear()}-W${String(getISOWeek(now)).padStart(2,'0')}`;

function extraireHostname(url) {
  try {
    const match = url.match(/^https?:\/\/([^\/]+)/);
    return match ? match[1] : url;
  } catch(e) { return url; }
}

const reponse = $input.first().json;
const results = reponse.results || [];

const articles = [];
for (const item of results) {
  const titre = (item.title || '').trim();
  const url   = item.url || '';
  if (!titre || !url) continue;
  const hash = crypto.createHash('sha256')
    .update(titre.toLowerCase().replace(/[^a-z0-9]/g,'').substring(0,60))
    .digest('hex').substring(0,16);
  articles.push({ json: {
    source_id: '17397726-3693-453f-bb4b-f7cb05d2c410',
    source_nom:       item.source || extraireHostname(url),
    titre,
    resume:           (item.content || item.snippet || '').substring(0, 500),
    url,
    image_url:        null,
    image_valide:     false,
    date_publication: item.published_date ? new Date(item.published_date).toISOString() : new Date().toISOString(),
    doublons_hash:    hash,
    semaine_id,
    selectionne:      false,
    collecteur:       'tavily'
  }});
}

console.log(`[CALAO Tavily] ${articles.length} articles normalisés`);
if (articles.length === 0) return [{ json: { skip: true } }];
return articles;

// CALAO — Dédoublonner tous les articles par hash
const items = $input.all();
const vus = new Set();
const resultat = [];

for (const item of items) {
  if (item.json.skip === true) continue;
  const hash = item.json.doublons_hash;
  if (!hash || vus.has(hash)) continue;
  vus.add(hash);
  resultat.push(item);
}

console.log(`[CALAO Dedup] ${items.length} reçus → ${resultat.length} uniques`);
if (resultat.length === 0) return [{ json: { skip: true, articles_count: 0 } }];
return resultat;

// ============================================================
// CALAO — Bloc 1 — Préparer body pour scoring Haiku
// Version 3 — limite 50 articles, format body string
// ============================================================

const items = $input.all();

const articlesValides = items.filter(item =>
  item.json.skip !== true &&
  item.json.url &&
  item.json.doublons_hash
);

if (articlesValides.length === 0) {
  return [{ json: { skip: true, articles_count: 0, body: null, items_originaux: [] } }];
}

const articlesCibles = articlesValides.slice(0, 50);

const liste = articlesCibles.map(item => ({
  id:     item.json.doublons_hash,
  titre:  (item.json.titre || '').substring(0, 100),
  resume: (item.json.resume || '').substring(0, 150)
}));

const systemPrompt = `Tu es un filtre éditorial pour CALAO, newsletter économique destinée aux entrepreneurs d'Afrique francophone.

Pour chaque article, attribue un score de pertinence :
5 = Impact économique direct (investissement, marché, financement, infrastructure)
4 = Politique publique ou réglementation changeant les règles du jeu
3 = Opportunité concrète, signal de marché, initiative entrepreneuriale
2 = Information économique périphérique, contexte régional utile
1 = Très faible pertinence mais acceptable
0 = Exclure absolument : gambling, jeux d'argent, faits divers criminels, sport, politique partisane sans dimension économique, religion, météo, people

RÈGLE IMPÉRATIVE : retourner un score pour chaque article soumis.
RETOURNE UNIQUEMENT un JSON valide sans markdown :
{"scores": [{"id": "identifiant", "score": 3}]}`;

const userMessage = `Évalue ces ${liste.length} articles :\n${JSON.stringify(liste)}`;

return [{
  json: {
    skip: false,
    articles_count: articlesCibles.length,
    body: JSON.stringify({
      model: 'anthropic/claude-haiku-4-5',
      max_tokens: 4000,
      temperature: 0.1,
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user',   content: userMessage }
      ]
    }),
    items_originaux: articlesCibles.map(item => item.json)
  }
}];

// CALAO — Bloc 1 — Filtrer par score Haiku
const SCORE_MINIMUM = 2;

const input = $input.first().json;

if (input.skip === true) {
  return [{ json: { articles_count: 0, skip: true } }];
}

const itemsOriginaux = $('Préparer body Haiku score').first().json.items_originaux || [];

let scores = {};
try {
  const reponse = $input.first().json;
  let texte = reponse.choices?.[0]?.message?.content || '';
  texte = texte.replace(/```json/g, '').replace(/```/g, '').trim();
  const jsonMatch = texte.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    (parsed.scores || []).forEach(s => { scores[s.id] = s.score; });
  }
  console.log(`[CALAO Bloc1] ${Object.keys(scores).length} scores reçus de Haiku`);
} catch(e) {
  console.warn('[CALAO Bloc1] Erreur parsing scores — fallback score 2 pour tous');
  itemsOriginaux.forEach(item => {
    if (item.doublons_hash) scores[item.doublons_hash] = 2;
  });
}

const resultat = [];
for (const item of itemsOriginaux) {
  if (item.skip === true) continue;
  if (!item.doublons_hash) continue;
  if (!item.url) continue;
  const score = scores[item.doublons_hash] ?? 0;
  if (score < SCORE_MINIMUM) {
    console.log(`[CALAO] Exclu score ${score} : ${(item.titre || '').substring(0, 60)}`);
    continue;
  }
  resultat.push({ json: { ...item, score_pertinence: score } });
}

if (resultat.length === 0) {
  return [{ json: { articles_count: 0, skip: true } }];
}

console.log(`[CALAO Bloc1] ${resultat.length} articles retenus (score >= ${SCORE_MINIMUM})`);
return resultat;

// CALAO — Log rapport final multi-sources
const semaine = $('Générer semaine_id').first().json.semaine_id;
console.log([
  '================================',
  'CALAO — Collecte multi-sources terminée',
  `Semaine : ${semaine}`,
  'Sources : RSS + SerpAPI + Tavily + GNews + NewsAPI',
  '================================'
].join('\n'));
return [{ json: { semaine_id: semaine, statut: 'collecte_terminee' } }];

